  boxShadow: '0 18px 50px rgba(0, 0, 0, 0.55), 0 0 40px rgba(212, 175, 55, 0.08)',
  backdropFilter: 'blur(18px) saturate(130%)',
  WebkitBackdropFilter: 'blur(18px) saturate(130%)',
